function invalidateCleanPreview(){cleanScanGeneration++;cleanPreview=null;id('fm-run-clean').disabled=true;id('fm-clean-list').innerHTML='';id('fm-clean-count').textContent=''}
function setCleanScanBusy(busy){cleanScanBusy=busy;for(const field of ['fm-clean-folder','fm-large','fm-old','fm-clean-scope-folder','fm-clean-scope-drives'])id(field).disabled=busy;id('fm-scan-clean').disabled=busy;id('fm-cancel-clean').disabled=!busy}
