function tab(name){if(!root.querySelector(`[data-fm-section="${name}"]`))name='organize';section=name;const primary=['organize','clean','junk'].includes(name)?'organize':name;root.querySelectorAll('[data-fm-tab]').forEach(x=>{let active=x.dataset.fmTab===primary;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1});root.querySelectorAll('[data-fm-subtab]').forEach(x=>{const active=x.dataset.fmSubtab===name;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active));x.tabIndex=active?0:-1});id('fm-organize-subnav').classList.toggle('fm-hidden',primary!=='organize');root.querySelectorAll('[data-fm-section]').forEach(x=>{let active=x.dataset.fmSection===name;x.classList.toggle('fm-hidden',!active);x.setAttribute('aria-hidden',String(!active))});notice(({organize:'按规则整理文件，或在上方切换到文件清理与深度清理。',rename:'选择文件并设置命名步骤，预览后执行。',clean:'扫描指定磁盘或文件夹中的安装包与大文件；勾选后移入回收站。',migrate:'默认扫描所有本机磁盘；可取消全选后勾选需要扫描的盘。',shred:'选择文件并检查完整列表；粉碎操作不可撤销。',junk:'集中查看系统、软件缓存、使用痕迹和回收站；确认勾选后再处理。',vault:'使用密码或恢复密钥管理本机加密文件。',rules:'调整规则并保存；自动整理仅处理启用后新增的稳定文件。',history:'可按批次或单文件撤销整理与命名。'})[name]);id('storage-full').classList.toggle('fm-hidden',name!=='clean'||cleanScope!=='drives');if(name==='organize'){loadOrganizeDrives();loadDuplicateDrives()}if(name==='clean'&&cleanScope==='drives')loadStorageDrives();if(name==='migrate')loadMigrationDrives();if(name==='history')loadHistory();if(name==='junk'){renderJunk();loadRecycleBinStatus()}if(name==='vault')loadVault();if(name==='rules')loadRules()}
