const listRenderVersions=new WeakMap();
async function list(el,items,type,selectByDefault=type!=='clean'&&type!=='migrate',isCurrent=()=>true){
 const box=id(el),version=(listRenderVersions.get(box)||0)+1;listRenderVersions.set(box,version);
 const rows=Array.isArray(items)?items:[],chunkSize=1200;
 box.setAttribute('aria-busy','true');
 box.innerHTML=`<progress class="fm-progress" max="${Math.max(rows.length,1)}" value="0" aria-label="正在显示扫描结果"></progress><div class="fm-summary" data-fm-render-status role="status" aria-live="polite">正在显示结果 0 / ${rows.length.toLocaleString()} 项…</div>`;
 const progress=box.querySelector('progress'),status=box.querySelector('[data-fm-render-status]');
 const current=()=>listRenderVersions.get(box)===version&&isCurrent();
 try{
  if(!rows.length){box.innerHTML='<p class="fm-muted">没有符合条件的文件。</p>';return true}
  for(let start=0;start<rows.length;start+=chunkSize){
   if(!current())return false;
   const end=Math.min(start+chunkSize,rows.length),html=rows.slice(start,end).map((p,index)=>{const i=start+index;return `<label class="fm-result"><input type="checkbox" data-fm-${type}="${i}" ${selectByDefault?'checked':''}><span><b>${e(type==='clean'?p.path.split('\\').pop():p.src.split('\\').pop())}</b><small>${type==='clean'?e(p.path):e(p.src)+' → '+e(p.dst)}</small></span><span class="fm-tag">${e(type==='clean'?p.reason:p.category)}</span></label>`}).join('');
   box.insertAdjacentHTML('beforeend',html);progress.value=end;
   if(end===rows.length||end%2000===0)status.textContent=`正在显示结果 ${end.toLocaleString()} / ${rows.length.toLocaleString()} 项…`;
   if(end<rows.length)await new Promise(resolve=>requestAnimationFrame(()=>resolve()));
  }
  return true;
 }finally{if(listRenderVersions.get(box)===version){box.removeAttribute('aria-busy');progress?.remove();status?.remove()}}
}
function selected(type){return [...root.querySelectorAll(`[data-fm-${type}]:checked`)].map(x=>Number(x.dataset['fm'+type.charAt(0).toUpperCase()+type.slice(1)]))}
function scanWarning(result,details=true){const count=Math.max(0,Number(result?.unreadableCount)||0);if(!count)return '';const sample=Array.isArray(result?.unreadablePaths)?result.unreadablePaths[0]:'';return `结果不完整：有 ${count} 个位置无法读取${details&&sample?'，例如 '+sample:''}。${details?'检查权限后可重新扫描。':''}`}
function result(r,verb,listId,countId,runId){const failed=Array.isArray(r?.failed)?r.failed:[],listNode=id(listId),countNode=id(countId);listNode.replaceChildren();id(runId).disabled=true;if(!r?.ok){countNode.textContent=`${verb}未完成，请重新预览后重试。`;notice(r?.error||'操作未完成，请重新预览后重试。',true);return}const moved=Math.max(0,Number(r.moved)||0);countNode.textContent=`${verb}结果：成功 ${moved} 个，失败 ${failed.length} 个。${failed.length?'请重新预览后重试失败文件。':'旧预览已清除。'}`;if(failed.length){const details=document.createElement('details'),summary=document.createElement('summary'),items=document.createElement('ul');summary.textContent=`查看失败文件（${failed.length}）`;for(const item of failed){const row=document.createElement('li');row.textContent=`${item.path||'未知文件'}：${item.error||'操作失败'}`;items.append(row)}details.append(summary,items);listNode.append(details)}notice(`${verb}完成：成功 ${moved} 个，失败 ${failed.length} 个${failed.length?'。失败项已列出，请重新预览后重试。':''}`,failed.length>0)}
function markOutcomeUnknown(verb,listId,countId,runId,recovery,statusId){const message=`${verb}请求中断，结果暂时无法确认。${recovery}`;id(listId).replaceChildren();id(countId).textContent=message;id(runId).disabled=true;if(statusId)id(statusId).textContent=message;notice(message,true)}
