function addStep(type='replace'){let row=document.createElement('div');row.className='fm-row fm-step';row.innerHTML=`<select class="input fm-step-type"><option value="replace">查找替换</option><option value="prefix">添加前缀</option><option value="suffix">添加后缀</option><option value="sequence">添加编号</option><option value="case">大小写</option><option value="spaces">空格替换</option></select><input class="input fm-step-find" placeholder="查找内容"><input class="input fm-step-value" placeholder="替换为 / 内容" style="flex:1"><label class="fm-regex"><input type="checkbox"> 正则</label><button class="btn small fm-step-remove">移除</button>`;row.querySelector('.fm-step-type').value=type;row.addEventListener('input',invalidateRenamePreview);row.addEventListener('change',invalidateRenamePreview);row.querySelector('.fm-step-remove').onclick=()=>{row.remove();invalidateRenamePreview()};id('fm-steps-empty')?.remove();id('fm-steps').append(row);invalidateRenamePreview();return row}id('fm-add-step').onclick=()=>addStep();
