function reportVaultImport(rawItem){
 const item=rawItem||{},name=item.name||'文件',warning=item.sourceStatusWarning?`；${item.sourceStatusWarning}`:'';
 if(item.sourceRecoveryPath){
  const recovery=item.sourceReplaced?`原路径已有其他文件，未覆盖；待恢复文件保留在 ${item.sourceRecoveryPath}`:`原文件暂存在 ${item.sourceRecoveryPath}，自动恢复未完成`;
  notice(`已加密；${recovery}：${name}${warning}`,true);
 }else if(item.sourceReplaced){
  notice(`已加密；原路径上的新文件已保留：${name}${warning}`,true);
 }else if(item.sourceChanged&&item.sourceRetained){
  notice(`已加密；检测到源文件变化，原文件已保留在原位置：${name}${warning}`,true);
 }else if(item.sourceChanged){
  notice(`已加密；源文件状态发生变化，未确认它仍在原位置，LxUltra 未将它移入回收站：${name}${warning}`,true);
 }else if(item.sourceRetained){
  notice(`已加密；原文件仍保留在原位置：${name}${warning}`,true);
 }else if(item.sourceStatusWarning){
  notice(`${item.sourceStatusWarning}；文件：${name}`,true);
 }else{
  notice(`已加密并移入回收站：${name}`);
 }
}
